import{_ as t,o as a,c as s,a4 as r}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"Version v1.1.0","description":"Notes de la version v1.1.0 de Teuthis-CMS.","frontmatter":{"title":"Version v1.1.0","description":"Notes de la version v1.1.0 de Teuthis-CMS."},"headers":[],"relativePath":"versions/v1-1-0.md","filePath":"versions/v1-1-0.md"}'),i={name:"versions/v1-1-0.md"};function n(o,e,c,l,u,d){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="version-v1-1-0" tabindex="-1">Version v1.1.0 <a class="header-anchor" href="#version-v1-1-0" aria-label="Permalink to &quot;Version v1.1.0&quot;">​</a></h1><p>Publiée le 20 août 2026. <a href="https://github.com/Bastien-OC20/calamars/releases/tag/v1.1.0" target="_blank" rel="noreferrer">La release sur GitHub</a>.</p><h2 id="v1-1-—-confiance-et-conformite" tabindex="-1">V1.1 — Confiance et conformité <a class="header-anchor" href="#v1-1-—-confiance-et-conformite" aria-label="Permalink to &quot;V1.1 — Confiance et conformité&quot;">​</a></h2><p>Clôture de la release V1.1 du plan d&#39;action (<code>docs/plan-action-agile.md</code>), qui complète le socle utilisable de V1 avec cinq chantiers portant sur la confiance, la conformité réglementaire et l&#39;exhaustivité fonctionnelle du CDC.</p><h3 id="epics-livres-dans-cette-release" tabindex="-1">Epics livrés dans cette release <a class="header-anchor" href="#epics-livres-dans-cette-release" aria-label="Permalink to &quot;Epics livrés dans cette release&quot;">​</a></h3><ul><li><p><strong>E9 (suite) — Détection d&#39;obsolescence par dérive de contenu et SEO assisté.</strong> Complète l&#39;Epic IA éditoriale : un signal de dérive de contenu ne peut structurellement jamais dépublier (garde-fou d&#39;origine <code>AI_SAFE_ACTIONS</code> hérité d&#39;E4) ; le SEO assisté propose titre et méta-description en régime <code>required</code>, jamais contournable même validation humaine désactivée globalement.</p></li><li><p><strong>E11 — Formulaires avancés.</strong> Un Content Type se déclare formulaire public sans toucher au Core (<code>form_config</code>). Page de relecture avant envoi et captcha serveur rendus non contournables par construction (<code>Literal</code> à valeur unique, signature de confirmation sans paramètre de données). Aucun vérificateur de captcha livré par défaut : une installation neuve refuse toute soumission publique tant qu&#39;un fournisseur n&#39;est pas branché plutôt que de dégrader silencieusement. Moteur de notifications multi-canal, fils de discussion agent ↔ usager par plugin. La SVE (Saisine par voie électronique) est désormais complète comme plugin — preuve du Plugin SDK (E7).</p></li><li><p><strong>E13 — Recherche complète.</strong> Recherche lexicale transverse à tous les Content Types et aux documents extraits par OCR, avec facettes, tris, autocomplétion (3 caractères, 7 suggestions) et suggestion orthographique. Synonymes et mots vides éditables par tenant via réécriture de requête à l&#39;application — les dictionnaires PostgreSQL, globaux à l&#39;instance, étant incompatibles avec une édition par tenant stockée en base (ADR-0016). Séparation stricte maintenue entre recherche lexicale et RAG sémantique.</p></li><li><p><strong>E12 — Comptes usagers.</strong> Authentification <code>end_users</code> (mot de passe local + OIDC/FranceConnect), strictement séparée des agents jusqu&#39;aux sessions (<code>end_user_sessions</code> distincte de <code>staff_sessions</code>, ADR-0003 poussée à son terme). Nouveau mécanisme Core : accès aux fichiers liés à une personne physique exclusivement par identifiant opaque, sans chemin, sans nom de fichier, sans listing de dossier possible (ADR-0017). Cycle de vie RGPD complet du compte (purge à 24h, relances à 20 mois puis 1 semaine avant 2 ans, suppression physique à 24 mois — durées paramétrables par tenant), export ZIP + CSV.</p></li><li><p><strong>E15 — Conformité générée.</strong> Politique de protection des données générée depuis le registre des traitements d&#39;E5, sans duplication. Déclaration d&#39;accessibilité générée depuis des résultats d&#39;audit humain saisis en base, sur un référentiel RGAA externalisé en YAML (jamais figé dans le code — prêt pour RGAA 5, ADR-0018) : aucun critère, niveau ou numérotation n&#39;est présumé par le code, vérifié par un test qui déroule un référentiel fictif de bout en bout. Aucun des deux documents générés n&#39;affirme de conformité réglementaire — le CMS n&#39;a pas obtenu de validation juridique à ce stade.</p></li></ul><h3 id="discipline-transverse-tenue-sur-toute-la-release" tabindex="-1">Discipline transverse tenue sur toute la release <a class="header-anchor" href="#discipline-transverse-tenue-sur-toute-la-release" aria-label="Permalink to &quot;Discipline transverse tenue sur toute la release&quot;">​</a></h3><p>Chaque Epic a fait l&#39;objet d&#39;une vérification indépendante avant intégration : lecture complète du diff, <code>ruff check</code> et <code>flake8</code> propres, round-trip Alembic complet (<code>upgrade</code> → <code>downgrade</code> → <code>upgrade</code>) sur base PostgreSQL fraîche, et suite de tests de recette rejouée sur base réelle migrée — sans régression sur les epics précédents à chaque étape.</p><h3 id="perimetre-non-couvert-par-cette-release" tabindex="-1">Périmètre non couvert par cette release <a class="header-anchor" href="#perimetre-non-couvert-par-cette-release" aria-label="Permalink to &quot;Périmètre non couvert par cette release&quot;">​</a></h3><p>V1.2 (&quot;Extension et plateforme&quot;) reste à livrer : E10 — Multi-site &amp; propagation, E14 — Cartographie, ainsi que le reste de la conformité générée listé en actions liées des ADR (référentiel d&#39;accessibilité, ordonnanceur de balayage du cycle de vie des comptes).</p><hr><p><em>Backend uniquement (<code>apps/api</code>). Le back-office (<code>apps/admin</code>, Nuxt 3) reste un scaffold non connecté à ces API.</em></p>',12)])])}const f=t(i,[["render",n]]);export{m as __pageData,f as default};
